// Navigation toggle
var CSbody=document.querySelector('body'),CSnavbarMenu=document.querySelector('#cs-navigation'),CShamburgerMenu=document.querySelector('#cs-navigation .cs-toggle');CShamburgerMenu.addEventListener('click',function(){CShamburgerMenu.classList.toggle('cs-active');CSnavbarMenu.classList.toggle('cs-active');CSbody.classList.toggle('cs-open');var csUL=document.querySelector('#cs-expanded'),csExpanded=csUL.getAttribute('aria-expanded');csUL.setAttribute('aria-expanded',csExpanded==='false'?'true':'false')});

// Dark mode
function enableDarkMode(){document.body.classList.add('dark-mode');localStorage.setItem('theme','dark')}function disableDarkMode(){document.body.classList.remove('dark-mode');localStorage.setItem('theme','light')}(function(){var theme='light';if(localStorage.getItem('theme'))theme=localStorage.getItem('theme');else if(window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches)theme='dark';theme==='dark'?enableDarkMode():disableDarkMode()})();document.getElementById('dark-mode-toggle').addEventListener('click',function(){localStorage.getItem('theme')==='light'?enableDarkMode():disableDarkMode()});

// Gallery toggle - incremental reveal
(function(){var gt=document.getElementById('gallery-toggle'),g=document.getElementById('gallery'),tt=gt.querySelector('.cs-toggle-text'),imgs=g.querySelectorAll('.cs-image'),grid=g.querySelector('.cs-gallery');function getCols(){var style=window.getComputedStyle(grid);var cols=style.gridTemplateColumns.split(' ').length;return Math.max(1,cols)}function getInitial(){var cols=getCols();if(cols===1)return 4;return cols*2}function init(){var show=getInitial();imgs.forEach(function(img,i){if(i<show){img.classList.remove('cs-hidden');img.classList.remove('cs-revealed')}else{img.classList.add('cs-hidden');img.classList.remove('cs-revealed')}});g.classList.remove('cs-fully-expanded');tt.textContent='View More'}function countVisible(){var c=0;imgs.forEach(function(img){if(!img.classList.contains('cs-hidden'))c++});return c}function reveal(){var cols=getCols(),batch=cols*2,hidden=[];imgs.forEach(function(img){if(img.classList.contains('cs-hidden'))hidden.push(img)});if(hidden.length===0){init();return}var toReveal=hidden.slice(0,batch);toReveal.forEach(function(el,i){el.classList.remove('cs-hidden');el.classList.add('cs-revealed');el.style.animationDelay=(i*0.1)+'s'});if(countVisible()>=imgs.length){g.classList.add('cs-fully-expanded');tt.textContent='View Less'}else{tt.textContent='View More'}}gt.addEventListener('click',reveal);requestAnimationFrame(function(){requestAnimationFrame(init)});window.addEventListener('resize',function(){if(!g.classList.contains('cs-fully-expanded'))init()})})();

// Testimonials Carousel
(function(){var items=document.querySelectorAll('#testimonials .cs-item'),prev=document.querySelector('#testimonials .cs-prev'),next=document.querySelector('#testimonials .cs-next'),dots=document.querySelector('#testimonials .cs-carousel-dots'),idx=0,auto,userPause;function createDots(){dots.innerHTML='';for(var i=0;i<items.length;i++){var d=document.createElement('button');d.classList.add('cs-carousel-dot');d.setAttribute('aria-label','Go to testimonial '+(i+1));if(i===0)d.classList.add('cs-active');(function(index){d.addEventListener('click',function(){go(index);pauseForUser()})})(i);dots.appendChild(d)}}function update(){for(var i=0;i<items.length;i++){items[i].classList.toggle('cs-active',i===idx)}var allDots=document.querySelectorAll('#testimonials .cs-carousel-dot');for(var i=0;i<allDots.length;i++){allDots[i].classList.toggle('cs-active',i===idx)}}function go(i){idx=i;if(idx>=items.length)idx=0;if(idx<0)idx=items.length-1;update()}function start(){auto=setInterval(function(){go(idx+1)},5000)}function stop(){clearInterval(auto)}function pauseForUser(){stop();clearTimeout(userPause);userPause=setTimeout(start,10000)}prev.addEventListener('click',function(){go(idx-1);pauseForUser()});next.addEventListener('click',function(){go(idx+1);pauseForUser()});var w=document.querySelector('#testimonials .cs-carousel-wrapper');w.addEventListener('mouseenter',stop);w.addEventListener('mouseleave',function(){clearTimeout(userPause);start()});createDots();items[0].classList.add('cs-active');start()})();

// Contact Modal
(function(){var m=document.getElementById('contact-modal'),ob=document.getElementById('contact-btn'),cb=m.querySelector('.cs-modal-close'),ov=m.querySelector('.cs-modal-overlay');function open(){m.classList.add('cs-active');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'}function close(){m.classList.remove('cs-active');m.setAttribute('aria-hidden','true');document.body.style.overflow=''}ob.addEventListener('click',open);cb.addEventListener('click',close);ov.addEventListener('click',close);document.getElementById('nav-contact-link').addEventListener('click',function(e){e.preventDefault();open()});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&m.classList.contains('cs-active'))close()});function dl(){var vc='BEGIN:VCARD\nVERSION:3.0\nN:Forster;Randy;;;\nFN:Randy Forster\nTITLE:Comedy Magician\nTEL;TYPE=CELL:+17036285154\nEMAIL:grforster@gmail.com\nADR;TYPE=WORK:;;Bethany Beach;Delaware;;;USA\nURL:https://randyforstermagic.com\nNOTE:Comedy Magician - Magic & Fun For All Occasions\nEND:VCARD',b=new Blob([vc],{type:'text/vcard'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='Randy_Forster.vcf';a.style.display='none';document.body.appendChild(a);a.click();setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(u)},100)}document.getElementById('save-contact-btn').addEventListener('click',dl);document.getElementById('footer-save-contact').addEventListener('click',dl)})();
